 const saveFinanceSettings=async(key,changes)=>{if(!onSaveSettings){update(d=>Object.assign(d,changes));return data}const previous=Object.fromEntries(Object.keys(changes).map(name=>[name,data[name]]));const alertId=beginAlert(t('Зберігаємо налаштування','Saving settings'));setSettingsSaving(key);update(d=>Object.assign(d,changes));try{const snapshot=await onSaveSettings(changes);setData(snapshot);finishAlert(alertId,'success',t('Налаштування збережено','Settings saved'));return snapshot}catch(error){update(d=>Object.assign(d,previous));finishAlert(alertId,'error',t('Не вдалося зберегти налаштування','Could not save settings'));throw error}finally{setSettingsSaving('')}};
