 // Pull-to-refresh uses a real in-flow reveal area, never a floating toast covering content.
 const pause=ms=>new Promise(resolve=>setTimeout(resolve,ms));
 const setPullHeight=(height,phase)=>{const slot=pullSlot.current;if(!slot)return;slot.dataset.phase=phase;slot.style.height=`${Math.max(0,height)}px`;slot.style.setProperty('--pull-visible',height>=64?'1':'0')};
  const refreshNow=async()=>{
  if(refreshLock.current)return;
  refreshLock.current=true;
  const sequence=++refreshSequence.current;
  setRefreshing(true);setRefreshFeedback('');setPullHeight(82,'loading');
  const started=Date.now();let ratesResult=null,serverSnapshot=null;
  try{
   // A pull-to-refresh is an explicit consistency boundary: query the Finance
   // API, not the old browser/demo store. The parent keeps the cache current.
   if(onRefresh)serverSnapshot=await onRefresh();
   const ctrl=new AbortController(),timer=setTimeout(()=>ctrl.abort(),5000);
   try{const response=await fetch('https://latest.currency-api.pages.dev/v1/currencies/uah.min.json',{cache:'no-store',signal:ctrl.signal});
    if(response.ok){const q=await response.json();const quotes=[q?.uah?.pln,q?.uah?.usd,q?.uah?.eur];if(/^\d{4}-\d{2}-\d{2}$/.test(q?.date||'')&&quotes.every(value=>typeof value==='number'&&Number.isFinite(value)&&value>0)){const rates={UAH:1,PLN:1/q.uah.pln,USD:1/q.uah.usd,EUR:1/q.uah.eur};if(Object.values(rates).every(value=>Number.isFinite(value)&&value>0&&value<1_000_000)){ratesResult={rates,rateDate:q.date,rateSource:'live'};writeFinanceRateCache(ratesResult)}}}
   }finally{clearTimeout(timer)}
  }catch{/* Keep the last confirmed snapshot if the device is offline. */}
  if(sequence===refreshSequence.current){
   setData(prev=>{
    const fresh=serverSnapshot||initialData||readStore();
    return {...fresh,theme:prev.theme,...(ratesResult||{})};
   });
   await pause(Math.max(0,480-(Date.now()-started)));
   setRefreshFeedback(ratesResult?'done':'offline');setPullHeight(82,ratesResult?'done':'offline');
   await pause(650);
   setPullHeight(0,'closing');await pause(290);
   if(sequence===refreshSequence.current){setPullHeight(0,'idle');setRefreshing(false);setRefreshFeedback('')}
  }
  refreshLock.current=false;
 };
 const pullStart=e=>{
  if(refreshLock.current||sheet||drawer||form||prefs||page==='onboarding'||main.current?.scrollTop>1||e.touches.length!==1||e.target.closest('input,button,textarea,select,[contenteditable="true"]'))return;
  pull.current={startX:e.touches[0].clientX,startY:e.touches[0].clientY,distance:0,mode:'pending'};
 };
 const pullMove=e=>{
  const gesture=pull.current,touch=e.touches[0];if(!gesture||!touch||refreshLock.current)return;
  const dx=touch.clientX-gesture.startX,dy=touch.clientY-gesture.startY;
  if(gesture.mode==='pending'){
   if(Math.abs(dx)>Math.abs(dy)||dy< -5||main.current?.scrollTop>1){pull.current=null;return}
   if(dy<8)return;gesture.mode='pulling';
  }
  if(dy<=0){gesture.distance=0;setPullHeight(0,'pulling');return}
  gesture.distance=Math.min(92,Math.max(0,(dy-8)*.65));
  setPullHeight(gesture.distance,gesture.distance>=72?'ready':'pulling');
 };
 const pullEnd=()=>{const gesture=pull.current;pull.current=null;if(!gesture)return;if(gesture.mode==='pulling'&&gesture.distance>=72)refreshNow();else setPullHeight(0,'closing')};
 const pullCancel=()=>{pull.current=null;if(!refreshLock.current)setPullHeight(0,'closing')};
 useEffect(()=>()=>{refreshSequence.current++;pull.current=null;refreshLock.current=false},[page]);
