 const txShares=tx=>Array.isArray(tx?.shares)?tx.shares:(tx?.shared?.debtId?[tx.shared]:[]);
 const applyShared=(d,tx,sign=1)=>{for(const share of txShares(tx)){
  if(!share?.debtId||!(share.amount>0))continue;
  const debt=d.debts.find(x=>x.id===share.debtId);if(!debt)continue;
  const effective=share.debtAmount??convert(share.amount,tx.currency,d.accounts.find(a=>a.id===debt.accountId)?.currency||share.debtCurrency||tx.currency,d.rates||rates);
  debt.amount=Math.max(0,Math.round((debt.amount+effective*sign)*100)/100);
  debt.remaining=Math.max(0,Math.round((debt.remaining+effective*sign)*100)/100);
 }};
