 if(split){
  if(!sharesDraft.length||sharesDraft.some(r=>!(Number(r.amount)>0)||((r.debtId||'new')==='new'&&!r.person?.trim()))||sharesDraft.reduce((sum,r)=>sum+Number(r.amount),0)>amt+0.000001){notify(t('Перевір суми й учасників: загальна частка не може бути більшою за витрату','Check participants and shares: total shares cannot exceed expense'));return false}
  const existing=sharesDraft.map(r=>r.debtId).filter(x=>x&&x!=='new');
  if(new Set(existing).size!==existing.length||existing.some(x=>!data.debts.find(d=>d.id===x&&d.direction==='owed'))){notify(t('Один борг не можна вибрати двічі','The same debt cannot be selected twice'));return false}
 }
 if(editing&&hasSharedRepayment(editing)){notify(t('Пов’язаний борг уже погашався — спершу перевір його історію','A linked debt has repayments. Review it before editing this expense'));return false}
 const oldShares=txShares(editing);
