 const tx={...draft,categoryId:needsCategory(draft)?draft.categoryId:null,id:editing?.id||id(),amount:amt,currency:a.currency,date:draft.date||today(),receivedAmount:draft.type==='transfer'?cv(amt,a.currency,b.currency):undefined,receivedCurrency:b?.currency,necessity:needsCategory(draft)&&draft.type==='expense'&&data.classifyExpenses?(draft.necessity||category(draft.categoryId)?.necessity||'optional'):undefined,shared:undefined,shares:split?shares:undefined};
