  setForm(null);setSheet(null);const guided=completeLesson();navigate(guided?'tutorial':editing?'history':'home');
  void onSaveLedgerEntry({draft:needsCategory(draft)?draft:{...draft,categoryId:null,necessity:undefined},editing, recurring:draft.recurringId?(()=>{const payment=data.recurring.find(row=>row.id===draft.recurringId);return payment?{id:payment.id,expectedOccurrenceAt:payment.nextOccurrenceAt,expectedVersion:payment.version}:undefined})():undefined})
   .then(snapshot=>{setData(snapshot);finishAlert(alertId,'success',t('Операцію збережено','Transaction saved'))})
