 if(item==='investAction'){const inv=(data.investments||[]).find(i=>i.id===sheet.id);if(!inv)return null;const mode=sheet.action;title=mode==='deposit'?t('Новий внесок','New contribution'):mode==='return'?t('Повернення коштів','Return funds'):t('Оцінка активу','Asset valuation');content=<InvestmentMovement key={inv.id+mode} inv={inv} mode={mode} accounts={activeAccounts} t={t} onSave={({amount,accountId})=>{const a=data.accounts.find(a=>a.id===accountId);if(!Number.isFinite(amount)||(mode==='valuation'?amount<0:amount<=0)||(mode!=='valuation'&&(!a||a.currency!==inv.currency))){notify(t('Перевір суму та рахунок','Check amount and account'));return}if(mode==='deposit'&&a.balance<amount){notify(t('Недостатньо коштів','Insufficient account balance'));return}if(mode==='return'&&amount>inv.value){notify(t('Повернення перевищує вартість активу','Return exceeds investment value'));return}update(d=>{const row=d.investments.find(i=>i.id===inv.id);const acct=d.accounts.find(a=>a.id===accountId);if(mode==='deposit'){row.invested+=amount;row.value+=amount;acct.balance-=amount}else if(mode==='return'){row.returned+=amount;row.value-=amount;acct.balance+=amount}else row.value=amount;row.events=[...(row.events||[]),{id:id(),date:today(),type:mode,amount,accountId:mode==='valuation'?null:accountId}]});setActiveInvestment(inv.id);setSheet(null);navigate('investmentDetail');notify(t('Інвестицію оновлено','Investment updated'))}}/>}
