 <div className="detail-meta recurring-detail-meta"><span>{t('Наступний платіж','Next payment')}</span><b>{x.next}</b><span>{t('Рахунок списання','Debit account')}</span><b><span className="meta-symbol">{ac?.emoji||'💳'}</span>{ac?.name||'—'}</b><span>{t('Повторення','Frequency')}</span><b>{repeatLabel(x,t)}</b><span>{t('Категорія','Category')}</span><b><span className="meta-symbol">{cat?.emoji||'🏷️'}</span>{catName(cat)}</b></div>
