 if(item==='debt'){const x=data.debts.find(r=>r.id===sheet.id);if(!x)return null;const ac=account(x.accountId),currency=ac?.currency||x.currency||data.currency;title=t('Борг','Debt');content=<><div className="detail-amount entity-preview debt-preview"><div className="entity-preview-heading"><span className="detail-emoji">{x.emoji||'🤝'}</span><b>{x.name}</b></div><h1>{fmt(x.remaining,currency)}</h1><p>{t('Залишок боргу','Remaining debt')}</p></div><div className="detail-meta debt-detail-meta"><span>{t('Тип боргу','Debt type')}</span><b>{x.direction==='owed'?t('Мені винні','Owed to me'):t('Я винен','I owe')}</b><span>{t('Рахунок','Account')}</span><b><span className="meta-symbol">{ac?.emoji||'💳'}</span>{ac?.name||'—'}</b><span>{t('Повернення до','Due date')}</span><b>{x.due||'—'}</b>{x.notes&&<><span>{t('Нотатка','Note')}</span><b>{x.notes}</b></>}</div><div className="inline-actions debt-entity-actions"><Button kind="secondary" onClick={()=>openEntity('debt',x)}><Pencil size={17}/>{t('Редагувати','Edit')}</Button><Button kind="danger" onClick={()=>setSheet({kind:'deleteDebt',id:x.id})}><Trash2 size={17}/>{t('Видалити','Delete')}</Button></div>{x.remaining>0&&<Button className="full debt-repay-action" kind="secondary" onClick={()=>setSheet({kind:'repay',id:x.id})}><CheckCircle2 size={18}/>{t('Записати погашення','Record repayment')}</Button>}</>}
