 if(item==='repay'){const x=data.debts.find(r=>r.id===sheet.id);if(!x)return null;title=t('Погашення боргу','Record repayment');const debtCurrency=account(x.accountId)?.currency||x.currency||data.currency;content=<RepayForm key={x.id} debt={x} currency={debtCurrency} accounts={activeAccounts} rates={rates} t={t} onSave={({debtAmount,accountAmount,accountId,inputCurrency})=>{const target=account(accountId);const amountInAccount=accountAmount;if(!target||!Number.isFinite(debtAmount)||debtAmount<=0||Math.round(debtAmount*100)>Math.round(x.remaining*100)){notify(t('Перевір суму та рахунок','Check amount and account'));return}if(x.direction==='owe'&&target.balance+0.000001<amountInAccount){notify(t('На рахунку недостатньо коштів','Insufficient account balance'));return}if(onSettleDebt){setBusy(t('Зберігаємо погашення','Saving repayment'));void onSettleDebt({id:x.id,accountId,amount:String(debtAmount),settlementDate:today()}).then(snapshot=>{setData(snapshot);close();notify(t('Погашення записано','Repayment saved'))}).catch(()=>notify(t('Не вдалося записати погашення','Could not save repayment'))).finally(()=>setBusy(''));return}update(d=>{const debt=d.debts.find(y=>y.id===x.id);const a=d.accounts.find(y=>y.id===accountId);if(!debt||!a)return;debt.remaining=Math.max(0,Math.round((debt.remaining-debtAmount)*100)/100);a.balance=Math.round((a.balance+(debt.direction==='owed'?1:-1)*amountInAccount)*100)/100;debt.repayments=[...(debt.repayments||[]),{id:id(),date:today(),amount:debtAmount,currency:debtCurrency,accountId,accountAmount:amountInAccount,accountCurrency:a.currency,inputCurrency,direction:debt.direction}]});close();notify(t('Погашення записано','Repayment saved'))}}/>}
