 const set=(k,v)=>{setErrors(err=>({...err,[k]:''}));setF(p=>({...p,[k]:v}))};const fail=(key,message)=>{setErrors(e=>({...e,[key]:message}));notify({kind:'error',message});return false};const title={account:t('Рахунок','Account'),category:t('Категорія','Category'),recurring:t('Регулярний платіж','Recurring payment'),debt:t('Борг','Debt'),profile:t('Редагування профілю','Edit profile')}[kind]||'';
