 if(kind==='recurring'){if(!f.title?.trim())return fail('title',t('Вкажи назву платежу','Enter a payment title'));if(!(Number(f.amount)>0))return fail('amount',t('Сума має бути більшою за нуль','Amount must be greater than zero'));if(onSaveRegularPayment){const recurrence=f.interval==='custom'?({days:'daily',weeks:'weekly',months:'monthly',years:'yearly'}[f.intervalUnit||'days']):f.interval==='quarterly'?'monthly':f.interval;const count=f.interval==='quarterly'?3:f.interval==='custom'?Math.max(1,Number(f.intervalCount)||1):1;void onSaveRegularPayment({id:editing?.id,values:{...f,interval:recurrence,intervalCount:count}}).then(snapshot=>onDone('recurring',snapshot)).catch(()=>fail('amount',t('Не вдалося зберегти платіж','Could not save payment')));return}update(d=>{const next={id:editing?.id||id(),title:f.title,amount:Number(f.amount),accountId:f.accountId,categoryId:f.categoryId,emoji:f.emoji,necessity:data.classifyExpenses?(f.necessity||data.categories.find(c=>c.id===f.categoryId)?.necessity||'optional'):undefined,interval:f.interval,intervalCount:Math.max(1,Number(f.intervalCount)||1),intervalUnit:f.intervalUnit||'days',next:f.next,status:f.status||'active'};d.recurring=editing?d.recurring.map(x=>x.id===editing.id?next:x):[...d.recurring,next]});return onDone('recurring')}
