function RepayForm({debt,currency,accounts,rates,t,onSave}){
 const [amount,setAmount]=useState(''),[accountId,setAccountId]=useState(()=>accounts.some(a=>a.id===debt.accountId)?debt.accountId:accounts[0]?.id||'');
 const [entryCurrency,setEntryCurrency]=useState('debt');
 const chosen=accounts.find(a=>a.id===accountId),n=Number(amount);const same=currency===chosen?.currency;
 const debtAmount=chosen?(entryCurrency==='account'?convert(n,chosen.currency,currency,rates):n):0;
 const accountAmount=chosen?(entryCurrency==='account'?n:convert(n,currency,chosen.currency,rates)):0;
 const paidOut=debt.direction==='owe',valid=!!chosen&&Number.isFinite(n)&&n>0&&debtAmount>0&&Math.round(debtAmount*100)<=Math.round(debt.remaining*100)&&(!paidOut||chosen.balance+0.000001>=accountAmount);
 const options=accounts.map(a=>({value:a.id,icon:a.emoji||'💳',label:a.name,sub:`${money(a.balance,a.currency)} · ${a.currency}`}));
 return <div className="repay-form"><p className="muted">{debt.name} · {t('залишилось','remaining')} {money(debt.remaining,currency)}</p><FormField label={paidOut?t('З якого рахунку списати *','Pay from account *'):t('На який рахунок зарахувати *','Receive into account *')}><ChoiceSelect title={paidOut?t('Рахунок для оплати','Payment account'):t('Рахунок отримання','Receiving account')} value={accountId} onChange={a=>{setAccountId(a);setAmount('');setEntryCurrency('debt')}} options={options}/></FormField>{chosen&&!same&&<div className="repay-currency-tabs" role="group" aria-label={t('У якій валюті вказати суму','Amount input currency')}><button type="button" className={entryCurrency==='debt'?'active':''} onClick={()=>{setAmount('');setEntryCurrency('debt')}}>{SYMBOL[currency]} · {t('Валюта боргу','Debt currency')}</button><button type="button" className={entryCurrency==='account'?'active':''} onClick={()=>{setAmount('');setEntryCurrency('account')}}>{SYMBOL[chosen.currency]} · {t('Валюта рахунку','Account currency')}</button></div>}
 <MoneyEntry key={`${accountId}-${entryCurrency}`} label={t('СУМА ПОГАШЕННЯ','REPAYMENT AMOUNT')} value={amount} onChange={setAmount} currency={entryCurrency==='account'&&chosen?chosen.currency:currency}/>
 {chosen&&!same&&<div className="repay-preview"><div><span>{t('Погашає борг','Reduces debt')}</span><b>{money(debtAmount,currency)}</b></div><div><span>{paidOut?t('Буде списано з рахунку','Debited from account'):t('Буде зараховано на рахунок','Credited to account')}</span><b>{money(accountAmount,chosen.currency)}</b></div><small>{t('Довідковий курс на момент операції','Indicative rate at transaction time')}</small></div>}
 {debtAmount>debt.remaining+0.005&&<p className="field-error">{t('Сума більша за залишок боргу','Amount exceeds the remaining debt')}</p>}{paidOut&&chosen&&accountAmount>chosen.balance&&<p className="field-error">{t('Недостатньо коштів на вибраному рахунку','Insufficient funds')}</p>}
 <Button className="full" disabled={!valid} onClick={()=>onSave({debtAmount,accountAmount,accountId,inputCurrency:entryCurrency==='account'?chosen.currency:currency})}>{t('Зберегти погашення','Save repayment')}</Button></div>;
}

function InvestmentForm({t,data,editing,onBack,onSave,onEmoji}){
 const [name,setName]=useState(editing?.name||''),[emoji,setEmoji]=useState(editing?.emoji||'📈');
 const [currency,setCurrency]=useState(editing?.currency||data.accounts.find(a=>!a.archivedAt)?.currency||'UAH');
 const [accountId,setAccountId]=useState(editing?.accountId||data.accounts.find(a=>!a.archivedAt)?.id||'');
 const [initialDeposit,setInitialDeposit]=useState('');
 return <><FormHeading onBack={onBack} t={t}>{editing?t('Редагувати інвестицію','Edit investment'):t('Новий актив','New investment')}</FormHeading><div className="form-grid"><NameEmojiField label={t('Назва активу *','Investment name *')} value={name} onChange={setName} emoji={emoji} onEmoji={()=>onEmoji(setEmoji)} placeholder={t('Наприклад, ETF або депозит','e.g. ETF or deposit')}/>{!editing&&<><FormField label={t('Рахунок для внесків *','Funding account *')}><ChoiceSelect value={accountId} onChange={v=>{setAccountId(v);setCurrency(data.accounts.find(a=>a.id===v)?.currency||data.currency)}} title={t('Рахунок','Account')} options={data.accounts.filter(a=>!a.archivedAt).map(a=>({value:a.id,icon:a.emoji,label:a.name,sub:SYMBOL[a.currency]}))}/></FormField><small className="field-help">{t('Валюта активу визначається рахунком:','Investment currency follows the account:')} <b>{SYMBOL[currency]} · {currency}</b></small><MoneyEntry value={initialDeposit} onChange={setInitialDeposit} currency={currency} label={t('ПЕРШИЙ ВНЕСОК','INITIAL CONTRIBUTION')}/><small className="field-help">{t('Можна залишити порожнім і поповнити пізніше.','Leave empty to invest later.')}</small></>}</div><p className="muted">{t('Після створення внеси кошти або вкажи оцінку в деталях активу.','After creating, add contributions or update valuation from investment details.')}</p><Button className="full form-save" disabled={!name.trim()||(!editing&&(!accountId||Number(initialDeposit)<0))} onClick={()=>onSave({name:name.trim(),emoji,currency,accountId,initialDeposit:Number(initialDeposit||0)})}>{t('Зберегти актив','Save investment')}</Button></>
}
function InvestmentMovement({inv,mode,accounts,t,onSave}){
 const [amount,setAmount]=useState(mode==='valuation'?String(inv.value):''),[accountId,setAccountId]=useState(inv.accountId||accounts[0]?.id||'');
 const validAccounts=accounts.filter(a=>a.currency===inv.currency);
 return <><MoneyEntry value={amount} onChange={setAmount} currency={inv.currency} label={mode==='valuation'?t('НОВА ОЦІНКА','NEW VALUATION'):t('СУМА','AMOUNT')}/>{mode!=='valuation'&&<FormField label={t('Рахунок','Account')}><ChoiceSelect value={accountId} onChange={setAccountId} title={t('Обери рахунок','Select account')} options={validAccounts.map(a=>({value:a.id,icon:a.emoji,label:a.name,sub:SYMBOL[a.currency]}))}/></FormField>}<p className="muted">{mode==='deposit'?t('Сума спишеться з рахунку й збільшить вартість активу.','Cash is deducted from your account and added to asset value.'):mode==='return'?t('Сума повернеться на рахунок і зменшить вартість активу.','Cash returns to the account and reduces asset value.'):t('Оцінка змінить тільки вартість активу, без руху коштів.','Valuation changes only the asset value, not your cash balance.')}</p><Button className="full" disabled={!amount||(mode==='valuation'?Number(amount)<0:Number(amount)<=0)||(mode!=='valuation'&&!validAccounts.some(a=>a.id===accountId))} onClick={()=>onSave({amount:Number(amount),accountId})}><Check size={18}/>{t('Зберегти','Save')}</Button></>
}
function InvestmentCloseForm({inv,accounts,t,fmt,onSave}){
 const eligible=accounts.filter(a=>a.currency===inv.currency),[closedAt,setClosedAt]=useState(today()),[accountId,setAccountId]=useState(inv.accountId||eligible[0]?.id||''),[finalReturn,setFinalReturn]=useState(''),[note,setNote]=useState(''),[saving,setSaving]=useState(false),[idempotencyKey]=useState(()=>crypto.randomUUID());
 const received=Number(finalReturn)||0,invested=Number(inv.invested)||0,returned=Number(inv.returned)||0,totalReceived=returned+received,result=totalReceived-invested;
 return <div className="investment-close-form"><div className="paper close-preview"><div><small>{t('Вкладено','Invested')}</small><b>{fmt(invested,inv.currency)}</b></div><div><small>{t('Отримано всього','Total received')}</small><b>{fmt(totalReceived,inv.currency)}</b></div><div><small>{result>=0?t('Прибуток','Profit'):t('Втрата','Loss')}</small><b className={result>=0?'positive':'negative'}>{fmt(result,inv.currency)}</b></div></div><FormField label={t('Дата закриття','Closing date')}><DateChoice title={t('Дата закриття','Closing date')} value={closedAt} onChange={setClosedAt} t={t}/></FormField><MoneyEntry label={t('ФІНАЛЬНЕ ПОВЕРНЕННЯ','FINAL RETURN')} value={finalReturn} onChange={setFinalReturn} currency={inv.currency}/>{received>0&&<FormField label={t('Рахунок для зарахування *','Receiving account *')}><ChoiceSelect value={accountId} onChange={setAccountId} title={t('Рахунок','Account')} options={eligible.map(a=>({value:a.id,icon:a.emoji,label:a.name}))}/></FormField>}<FormField label={t('Інсайти та нотатка','Insights and note')}><textarea rows="4" value={note} onChange={e=>setNote(e.target.value)} placeholder={t('Що спрацювало, що варто змінити наступного разу…','What worked and what you would change next time…')}/></FormField><Button className="full" disabled={saving||!closedAt||(received>0&&!accountId)} onClick={async()=>{setSaving(true);try{await onSave({closedAt,accountId,finalReturn:received,note,idempotencyKey})}finally{setSaving(false)}}}><CheckCircle2 size={18}/>{saving?t('Закриваємо…','Closing…'):t('Підтвердити закриття','Confirm closing')}</Button></div>
}
